"use client";

import { useId, useLayoutEffect, useRef } from "react";
import type { FieldsetHTMLAttributes, ReactNode } from "react";
import "./styles/skeuo-radio-group.css";

export type SkeuoRadioOption = { value: string; label: ReactNode; disabled?: boolean };

export type SkeuoRadioGroupProps = Omit<
  FieldsetHTMLAttributes<HTMLFieldSetElement>,
  "children" | "onChange"
> & {
  label: string;
  value: string;
  options: readonly SkeuoRadioOption[];
  onValueChange: (value: string) => void;
  required?: boolean;
};

export function SkeuoRadioGroup({
  label, value, options, onValueChange, required, name, form, className = "", ...props
}: SkeuoRadioGroupProps) {
  const id = useId();
  const scroll = useRef<HTMLDivElement>(null);
  const rows = useRef<HTMLDivElement>(null);
  const marker = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    const viewport = scroll.current;
    const list = rows.current;
    const indicator = marker.current;
    if (!viewport || !list || !indicator) return;

    const selected = list.querySelector("input:checked")?.closest<HTMLElement>(".sk-radio-option");
    if (!selected) {
      delete indicator.dataset.ready;
      return;
    }

    function update(keepSelectionVisible: boolean) {
      if (!viewport || !list || !indicator || !selected) return;
      const top = selected.offsetTop;
      const height = selected.offsetHeight;
      const center = top + height / 2;
      const previous = parseFloat(indicator.style.getPropertyValue("--sk-radio-marker-y"));
      const outside = top < viewport.scrollTop || top + height > viewport.scrollTop + viewport.clientHeight;
      if (keepSelectionVisible && outside && center !== previous) {
        viewport.scrollTop = Math.max(0, top - (viewport.clientHeight - height) / 2);
      }
      if (center === previous && indicator.dataset.ready) return;
      indicator.dataset.animate = String(!!indicator.dataset.ready && !outside && Math.abs(center - previous) <= 156);
      indicator.style.setProperty("--sk-radio-marker-y", `${center}px`);
      indicator.dataset.ready = "true";
    }

    update(true);
    const observer = new ResizeObserver(() => update(false));
    observer.observe(list);
    for (const row of list.querySelectorAll(".sk-radio-option")) observer.observe(row);
    return () => observer.disconnect();
  }, [value, options]);

  if (!options.length) return null;

  return (
    <fieldset {...props} form={form} data-sk-root="" className={`sk-radio-group ${className}`.trim()}>
      <legend className="sk-radio-legend">{label}</legend>
      <div ref={scroll} className="sk-radio-scroll">
        <div ref={rows} className="sk-radio-rows">
          <span className="sk-radio-rail" aria-hidden="true" />
          {options.map((option) => (
            <label className="sk-radio-option" key={option.value}>
              <input
                type="radio"
                data-sk-selection-sound="radio"
                name={name ?? id}
                form={form}
                value={option.value}
                checked={option.value === value}
                disabled={option.disabled}
                required={required}
                onChange={() => onValueChange(option.value)}
              />
              <span className="sk-radio-notch" aria-hidden="true" />
              <span className="sk-radio-label">{option.label}</span>
            </label>
          ))}
          <span ref={marker} className="sk-radio-marker" aria-hidden="true" />
        </div>
      </div>
    </fieldset>
  );
}

@import "./skeuo-base.css";

:where(.light, [data-theme="light"]) { --sk-radio-scheme: light; }
:where(.dark, [data-theme="dark"]) { --sk-radio-scheme: dark; }

.sk-radio-group {
  color-scheme: var(--sk-radio-scheme, light dark);
  display: block;
  inline-size: 100%;
  max-inline-size: 420px;
  min-inline-size: 0;
  margin: 0;
  padding: 5px 5px 7px;
  border: 1px solid light-dark(#748279, #526258);
  border-radius: 18px;
  background: linear-gradient(142deg, light-dark(#fcfefc, #69776e), light-dark(#b1bdb5, #353f39) 42%,
    light-dark(#e0e8e2, #59665d) 72%, light-dark(#7d8c82, #222e27));
  box-shadow: inset 0 1px #f7fff5cc, inset 1px 0 #e0ece591, inset 0 -2px 2px #17291e80,
    0 2px light-dark(#829086, #26362d), 0 4px light-dark(#637168, #111d16),
    0 8px 14px light-dark(#23352d38, #0000008f);
}
.sk-radio-legend {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  padding: 0;
  white-space: nowrap;
  clip-path: inset(50%);
  overflow: hidden;
}
.sk-radio-scroll {
  max-block-size: 340px;
  overflow-y: auto;
  overscroll-behavior-y: contain;
  scrollbar-width: thin;
  border: 1px solid light-dark(#819087, #4d6053);
  border-radius: 13px;
  background: linear-gradient(light-dark(#f7f9f7, #28332c), light-dark(#e8ede9, #1c251f));
  box-shadow: inset 0 3px 5px light-dark(#34483b40, #080e0bb8),
    inset 1px 0 3px light-dark(#34483b24, #080e0b66), inset 0 -1px light-dark(#ffffffb8, #899d8d40);
}
.sk-radio-rows { position: relative; padding-block: 3px; }
.sk-radio-rail {
  position: absolute;
  inset-block: 8px;
  inset-inline-start: 10px;
  inline-size: 25px;
  border-radius: 13px;
  background: linear-gradient(light-dark(#18291f38, #070e093d), transparent 12%, transparent 88%,
    light-dark(#18291f1a, #070e091f)),
    linear-gradient(90deg, light-dark(#3a4c41, #12221a), light-dark(#53685a, #20362a) 18%,
      light-dark(#718578, #354d40) 70%, light-dark(#8fa095, #566c5e));
  box-shadow: inset 0 1px 2px #13241a36;
  pointer-events: none;
}
.sk-radio-option {
  display: flex;
  position: relative;
  align-items: center;
  min-block-size: 52px;
  padding-block: 3px;
  padding-inline: 43px 4px;
  color: light-dark(#202923, #edf1ed);
  cursor: pointer;
}
.sk-radio-option:not(:last-of-type)::after {
  content: "";
  position: absolute;
  inset-block-end: 0;
  inset-inline: 46px 0;
  border-block-end: 1px solid light-dark(#c7d2ca, #47594d);
  pointer-events: none;
}
.sk-radio-option input {
  position: absolute;
  inset-inline-start: 15px;
  inset-block-start: 50%;
  inline-size: 15px;
  block-size: 15px;
  margin: 0;
  transform: translateY(-50%);
  opacity: 0;
}
.sk-radio-option:has(input:disabled) { opacity: .45; cursor: not-allowed; }
.sk-radio-option:active:not(:has(input:disabled)) { background: light-dark(#345f4815, #dcefe116); }
.sk-radio-label {
  flex: 1;
  min-inline-size: 0;
  padding: 10px 6px;
  border-radius: 7px;
  font-size: 17px;
  line-height: 23px;
  overflow-wrap: anywhere;
}
.sk-radio-option input:checked ~ .sk-radio-label {
  background: light-dark(#d9e7dda0, #395447b3);
  color: var(--primary, light-dark(#294f3e, #b6d1be));
  font-weight: 700;
}
.sk-radio-option input:focus-visible ~ .sk-radio-label {
  outline: 2px solid var(--sk-ring);
  outline-offset: -2px;
}
.sk-radio-notch {
  position: absolute;
  inset-inline-start: 15px;
  inset-block-start: calc(50% - 1px);
  inline-size: 15px;
  block-size: 2px;
  background: light-dark(#33443a, #0c1811);
  box-shadow: 0 1px light-dark(#f7fff5c7, #c9dbc955);
  pointer-events: none;
}
.sk-radio-marker {
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 9px;
  inline-size: 27px;
  block-size: 22px;
  transform: translateY(calc(var(--sk-radio-marker-y, 0px) - 11px));
  visibility: hidden;
  border: 1px solid light-dark(#294b3e, #6f8a79);
  border-radius: 5px;
  background: light-dark(#213c32, #3d5b4c);
  box-shadow: 0 2px #20392de0, 0 4px 5px #10251cb3;
  pointer-events: none;
}
.sk-radio-marker[data-ready="true"] { visibility: visible; }
.sk-radio-marker[data-animate="true"] { transition: transform 260ms cubic-bezier(.24, .78, .3, 1); }
.sk-radio-marker::before {
  content: "";
  position: absolute;
  inset: 1px 1px 3px;
  border-radius: 3px;
  background: linear-gradient(light-dark(#aecfbb, #d6ead9) 0%,
    var(--primary, light-dark(#54836d, #9ab5a6)) 30%, light-dark(#365e50, #698b78));
  box-shadow: inset 0 1px #f1ffefdb, inset 1px 0 #e3ffe478, inset 0 -2px #142d2175;
}

@media (prefers-reduced-motion: reduce) {
  .sk-radio-marker[data-animate="true"] { transition: none; }
}
@media (forced-colors: active) {
  .sk-radio-rail, .sk-radio-notch, .sk-radio-marker[data-ready="true"] { display: none; }
  .sk-radio-option input { opacity: 1; }
}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
